private void processOptionToken(final String token, final boolean stopAtNonOption)
{
    if (stopAtNonOption && !options.hasOption(token))
    {
        eatTheRest = true;
    }

    if (options.hasOption(token))
    {
        currentOption = options.getOption(token);
    }

    tokens.add(token);
}

public static <T> T createValue(final String str, final Class<T> clazz) throws ParseException
{
    if (PatternOptionBuilder.STRING_VALUE == clazz)
    {
        return (T) str;
    }
    else if (PatternOptionBuilder.OBJECT_VALUE == clazz)
    {
        return (T) createObject(str);
    }
    else if (PatternOptionBuilder.NUMBER_VALUE == clazz)
    {
        return (T) createNumber(str);
    }
    else if (PatternOptionBuilder.DATE_VALUE == clazz)
    {
        return (T) createDate(str);
    }
    else if (PatternOptionBuilder.CLASS_VALUE == clazz)
    {
        return (T) createClass(str);
    }
    else if (PatternOptionBuilder.FILE_VALUE == clazz)
    {
        return (T) createFile(str);
    }
    else if (PatternOptionBuilder.EXISTING_FILE_VALUE == clazz)
    {
        return (T) openFile(str);
    }
    else if (PatternOptionBuilder.FILES_VALUE == clazz)
    {
        return (T) createFiles(str);
    }
    else if (PatternOptionBuilder.URL_VALUE == clazz)
    {
        return (T) createURL(str);
    }
    else
    {
        throw new ParseException("Unable to handle the class: " + clazz);
    }
}

protected void processOption(final String arg, final ListIterator<String> iter) throws ParseException
{
    final boolean hasOption = getOptions().hasOption(arg);

    // if there is no option throw an UnrecognizedOptionException
    if (!hasOption)
    {
        throw new UnrecognizedOptionException("Unrecognized option: " + arg, arg);
    }

    // get the option represented by arg
    final Option opt = (Option) getOptions().getOption(arg).clone();

    // update the required options and groups
    updateRequiredOptions(opt);

    // if the option takes an argument value
    if (opt.hasArg())
    {
        processArgs(opt, iter);
    }

    // set the option on the command line
    cmd.addOption(opt);
}

static void validateOption(final String opt) throws IllegalArgumentException
{
    // if opt is NULL do not check further
    if (opt == null)
    {
        return;
    }

    // handle the single character opt
    if (opt.length() == 1)
    {
        final char ch = opt.charAt(0);

        if (!isValidOpt(ch))
        {
            throw new IllegalArgumentException("Illegal option name '" + ch + "'");
        }
    }

    // handle the multi character opt
    else
    {
        for (final char ch : opt.toCharArray())
        {
            if (!isValidChar(ch))
            {
                throw new IllegalArgumentException("The option '" + opt + "' contains an illegal "
                                                   + "character : '" + ch + "'");
            }
        }
    }
}

