private static String createMessage(final String option, final Collection<String> matchingOptions)
{
    final StringBuilder buf = new StringBuilder("Ambiguous option: '");
    buf.append(option);
    buf.append("'  (could be: ");

    final Iterator<String> it = matchingOptions.iterator();
    while (it.hasNext())
    {
        buf.append("'");
        buf.append(it.next());
        buf.append("'");
        if (it.hasNext())
        {
            buf.append(", ");
        }
    }
    buf.append(")");

    return buf.toString();
}

private void updateRequiredOptions(final Option opt) throws ParseException
{
    // if the option is a required option remove the option from
    // the requiredOptions list
    if (opt.isRequired())
    {
        getRequiredOptions().remove(opt.getKey());
    }

    // if the option is in an OptionGroup make that option the selected
    // option of the group
    if (getOptions().getOptionGroup(opt) != null)
    {
        final OptionGroup group = getOptions().getOptionGroup(opt);

        if (group.isRequired())
        {
            getRequiredOptions().remove(group);
        }

        group.setSelected(opt);
    }
}

