private boolean isLongOption(final String token)
{
    if (!token.startsWith("-") || token.length() == 1)
    {
        return false;
    }

    final int pos = token.indexOf("=");
    final String t = pos == -1 ? token : token.substring(0, pos);

    if (!getMatchingLongOptions(t).isEmpty())
    {
        // long or partial long options (--L, -L, --L=V, -L=V, --l, --l=V)
        return true;
    }
    else if (getLongPrefix(token) != null && !token.startsWith("--"))
    {
        // -LV
        return true;
    }

    return false;
}

protected int findWrapPos(final String text, final int width, final int startPos)
{
    // the line ends before the max wrap pos or a new line char found
    int pos = text.indexOf('\n', startPos);
    if (pos != -1 && pos <= width)
    {
        return pos + 1;
    }

    pos = text.indexOf('\t', startPos);
    if (pos != -1 && pos <= width)
    {
        return pos + 1;
    }

    if (startPos + width >= text.length())
    {
        return -1;
    }

    // look for the last whitespace character before startPos+width
    for (pos = startPos + width; pos >= startPos; --pos)
    {
        final char c = text.charAt(pos);
        if (c == ' ' || c == '\n' || c == '\r')
        {
            break;
        }
    }

    // if we found it - just return
    if (pos > startPos)
    {
        return pos;
    }

    // if we didn't find one, simply chop at startPos+width
    pos = startPos + width;

    return pos == text.length() ? -1 : pos;
}

